// Aufgaben-Erzeuger, Teil 8: Oberstufe – offene Lehrplan-Themen (Paket 0.33).
// Umkehr- und Wurzelfunktion, Integralfunktion, Newton-Verfahren, Ortskurven · Hesse-Form, Schnittgerade, windschiefe Geraden,
// Spiegelung, Bewegung · zweiseitiger Test, Histogramm, Fragen rückwärts, stetige Zufallsgrößen, Mengenschreibweise.
// Gleiche Regeln wie in gen.js: Stufe lv (1–5), Ablenker = typische Fehler mit Diagnose, mindestens zwei Tipps.
// Stufen-Auftrag (16.11.2026): Jede Stufe hat eigene Aufgaben-Arten. Stufe 4 und 5 sind mehrschrittig (Parameter, Scharen, Anwendungen,
// unschöne Zahlen) und zeigen den vollständigen Lösungsweg mit den Namen der Regeln. Unabhängig nachgerechnet in tests/hart/gen89.mjs.
import { ri, pick, shuffle, rand, ft, fmt } from './math.js';
import { tex } from './ui.js';
import { tier, par, vecTex, uniq, uniqNum } from './gen.js';

const N = (num, correct, why, t) => ({ tex: t ?? ft(num, 3), num, correct, why });
const T = (t, correct, why) => ({ tex: t, correct, why });
const gut = (o) => o.every((x) => Number.isFinite(x.num)) && uniqNum(o) && uniq(o);
/** Auch beim Eintippen eindeutig: Kein Ablenker darf – auf die gezeigten Nachkommastellen gerundet – wie die richtige Antwort aussehen. */
const tippfest = (o) => { const r = o.find((x) => x.correct), st = (String(r.tex).match(/\{,\}(\d+)$/) || ['', ''])[1].length, e = 0.6 * 10 ** -st; return o.every((x) => x.correct || Math.abs(x.num - r.num) > e); };
const fertig = (prompt, formula, opts, hints, explain, kind, extra = {}) => ({ prompt, formula, options: shuffle(opts), hints, explain, kind, ...extra });
const dfrac = (a, b) => `\\dfrac{${a}}{${b}}`;
const P3 = (n, v) => `${n}(${v.map((c) => ft(c)).join('\\mid ')})`;
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const ebene = (n, d) => `${n.map((c, i) => (c === 0 ? '' : `${c > 0 ? '+' : '-'}${Math.abs(c) === 1 ? '' : Math.abs(c)}x_${i + 1}`)).join('').replace(/^\+/, '')}=${ft(d)}`;
const lin = (m, b, v = 'x') => `${m === 1 ? '' : m === -1 ? '-' : ft(m)}${v}${b === 0 ? '' : b > 0 ? `+${ft(b)}` : ft(b)}`;
/* Helfer für die oberen Stufen (Stufen-Auftrag 16.11.2026): Brüche, Vorzeichen, Antworten mit Rechenwert `val` für die Prüfdatei tests/hart/gen89.mjs. */
const ggT = (a, b) => (b ? ggT(b, a % b) : Math.abs(a));
/** Gekürzter Bruch als Formel; ganze Zahlen ohne Bruchstrich. */
const br = (z, n) => { if (n < 0) { z = -z; n = -n; } const d = ggT(z, n) || 1, a = z / d, b = n / d; return b === 1 ? `${a}` : `${a < 0 ? '-' : ''}${dfrac(Math.abs(a), b)}`; };
/** Zahl mit Vorzeichen („+3“, „-2,5“) und Summand mit Buchstabe („+3t“, „-t“, bei 0 nichts). */
const vz = (n, d = 2) => (n < 0 ? `-${ft(-n, d)}` : `+${ft(n, d)}`);
const kt = (c, v) => (c === 0 ? '' : `${c > 0 ? '+' : '-'}${Math.abs(c) === 1 ? '' : ft(Math.abs(c))}${v}`);
/** Antwort mit Formel und Rechenwert (Zahl oder Liste) – ohne `num`, also nicht zum Eintippen. */
const V = (t, val, correct, why) => ({ tex: t, val, correct, why });
/** Bruch-Antwort mit Zahlwert. */
const B = (z, n, correct, why) => ({ tex: br(z, n), num: z / n, correct, why });
const gleich = (a, b) => { const x = [].concat(a), y = [].concat(b); return x.length === y.length && x.every((v, i) => Math.abs(v - y[i]) < 1e-7 || (!Number.isFinite(v) && v === y[i])); };
/** Alle Antworten verschieden – in der Schreibweise und im Rechenwert. */
const klar = (o) => uniq(o) && o.every((a, i) => o.every((b, j) => i >= j || a.val === undefined || b.val === undefined || !gleich(a.val, b.val)));
const weit = (o, e = 0.01) => o.every((a, i) => o.every((b, j) => i >= j || Math.abs(a.num - b.num) > e));
const grad1 = (x) => +((x * 180) / Math.PI).toFixed(1);

