      const opts = [V(`f^{-1}(x)=${d}+${w(1)}`, g((x) => d + Math.sqrt(x - e)), true), V(`f^{-1}(x)=${d}-${w(1)}`, g((x) => d - Math.sqrt(x - e)), false, `Wegen ${tex(`x\\ge ${d}`)} ist der rechte Parabelast gemeint – dazu gehört die positive Wurzel.`), V(`f^{-1}(x)=${w(1)}-${d}`, g((x) => Math.sqrt(x - e) - d), false, `Aus ${tex(`x-${d}=\\sqrt{\\dots}`)} wird ${tex(`x=${d}+\\sqrt{\\dots}`)}: Die ${d} wird addiert.`), V(`f^{-1}(x)=${d}+${w(-1)}`, g((x) => d + Math.sqrt(x + e)), false, `Die Zahl ${tex(ft(e))} aus der Scheitelform wechselt beim Herüberbringen ihr Vorzeichen.`)];
