    if (kind === 'ablumkehr') { const a = ri(1, 6), b0 = ri(-5, 5), x0 = pick([2, 3, -2]), y0 = x0 ** 3 + a * x0 + b0, s = 3 * x0 * x0 + a, fx = `x^3${kt(a, 'x')}${b0 === 0 ? '' : vz(b0)}`;
      const opts = [V(dfrac(1, s), 1 / s, true), V(dfrac(1, 3 * y0 * y0 + a), 1 / (3 * y0 * y0 + a), false, `Abgeleitet wird an der Stelle ${tex('x_0')} mit ${tex(`f(x_0)=${y0}`)} – nicht an der Stelle ${y0} selbst.`), V(`${s}`, s, false, 'Das ist die Steigung von f. Die Umkehrfunktion hat dort den Kehrwert als Steigung.'), V(dfrac(1, x0 * x0 + a), 1 / (x0 * x0 + a), false, `${tex(`f'(x)=3x^2+${a}`)} – der Faktor 3 aus der Potenzregel fehlt.`)];
      if (!klar(opts)) continue; return fertig(`f ist streng monoton wachsend und deshalb umkehrbar. Berechne die Ableitung der Umkehrfunktion an der Stelle ${y0}, also ${tex(`(f^{-1})'(${y0})`)}.`, `f(x)=${fx}`, opts, [`Umkehrregel: ${tex(`(f^{-1})'(y_0)=${dfrac(1, "f'(x_0)")}`)} mit ${tex('f(x_0)=y_0')}. Der Term der Umkehrfunktion wird dafür nicht gebraucht.`, `Die passende Stelle ${tex('x_0')} findet man durch Probieren: ${tex(`f(${x0})=${par(x0)}^3${a === 1 ? '+' : `+${a}\\cdot`}${par(x0)}${b0 === 0 ? '' : vz(b0)}=${y0}`)}, also ${tex(`x_0=${x0}`)}.`, `Potenzregel: ${tex(`f'(x)=3x^2+${a}`)}, also ${tex(`f'(${x0})=3\\cdot${x0 * x0}+${a}=${s}`)}.`, `Kehrwert bilden: ${tex(`(f^{-1})'(${y0})=${dfrac(1, s)}`)}.`], `${tex(`f(${x0})=${y0}`)}, ${tex(`f'(${x0})=3\\cdot${x0 * x0}+${a}=${s}`)}; nach der Umkehrregel ist ${tex(`(f^{-1})'(${y0})=${dfrac(1, `f'(${x0})`)}=${dfrac(1, s)}`)}.`, kind, { probe: { a, b0, x0, y0 } }); }
