      const opts = [T(`x${zeichen}${ft(gr)}`, true), T(`x${neg ? '\\ge' : '\\le'}${ft(gr)}`, false, neg ? 'Beim Teilen durch eine negative Zahl dreht sich das Ungleichheitszeichen um.' : 'Der Ausdruck unter der Wurzel darf nicht negativ sein.'), T(`x${zeichen}${ft(-gr)}`, false, 'Beim Umstellen wechselt das Vorzeichen.'), T('x\\in\\mathbb{R}', false, 'Unter einer Wurzel darf keine negative Zahl stehen.')];
