const bin = (n, k) => { let r = 1; for (let j = 0; j < k; j++) r = (r * (n - j)) / (j + 1); return Math.round(r); };
const bpdf = (n, p, k) => (k < 0 || k > n ? 0 : bin(n, k) * p ** k * (1 - p) ** (n - k));
const bcdf = (n, p, k) => { let s = 0; for (let j = 0; j <= Math.min(n, k); j++) s += bpdf(n, p, j); return s; };
