    const W = (v, c, w) => N(+v.toFixed(4), c, w, form === 'ohne' || form === 'erwart' ? v.toFixed(4).replace('.', '{,}') : ft(+v.toFixed(4), 4));   // „vier Nachkommastellen“ verlangt: Endnullen zeigen
