      const opts = [W(r, true), n === 2 ? W(b / 2, false, `Potenzieren heißt malnehmen, nicht teilen: ${tex(`${ft(b)}^2=${ft(b)}\\cdot ${ft(b)}`)}.`) : W(b ** (n - 1), false, `Es sind ${n} Versuche – ein Faktor fehlt.`), W(b, false, `Das gilt für einen einzigen Versuch – hier sind es ${n}.`), W(1 - r, false, 'Das ist das Gegenereignis.')];
