      const opts = [W(r, true), W(1 - p0, false, 'Das ist „mindestens eines“. Bei „mindestens zwei“ gehört auch „genau eines“ zum Gegenereignis.'), W(p0 + p1, false, 'Das ist das Gegenereignis „höchstens eines“.'), W(1 - p1, false, `Auch ${tex('P(X=0)')} muss abgezogen werden.`)];
