    if (k < 1 || k >= n - 1) continue;
    if (kind === 'summe') { const a = f(0), b = f(1), c = f(2), r = +(a + b + c).toFixed(4); const opts = [W(r, true), W(c, false, '„Höchstens 2“ umfasst auch 0 und 1 Treffer.'), W(+(a + b).toFixed(4), false, 'Die 2 gehört bei „höchstens 2“ dazu.'), W(+(1 - r).toFixed(4), false, 'Das ist das Gegenereignis „mehr als 2“.')];
      if (!gut(opts) || !tippfest(opts)) continue; return fertig(`${kopf} Gegeben sind die Einzelwahrscheinlichkeiten ${tex(`P(X=0)=${ft(a, 4)}`)}, ${tex(`P(X=1)=${ft(b, 4)}`)}, ${tex(`P(X=2)=${ft(c, 4)}`)}. Wie groß ist die kumulierte Wahrscheinlichkeit ${tex('P(X\\le 2)')}?`, undefined, opts, ['Kumuliert heißt: aufsummiert.', `${tex('P(X\\le 2)=P(X=0)+P(X=1)+P(X=2)')}.`], `${tex(`${ft(a, 4)}+${ft(b, 4)}+${ft(c, 4)}=${ft(r, 4)}`)}.`, kind, { n, p, r }); }
